package dl
import "net/http"
func Ping(u string) error {
	resp, err := http.Get(u)
	if err != nil { return err }
	defer resp.Body.Close()
	return nil
}

files.tx.go:
package tx
import "database/sql"
func Store(db *sql.DB) error {
	tx, err := db.Begin()
	if err != nil { return err }
	defer tx.Rollback()
	return tx.Commit()
}

